use std::collections::BTreeMap;

use flatc_rs_schema::resolved::ResolvedSchema;

use super::namespace_tree::{self, NamespaceNode, TypeEntry};
use super::ts_enum_gen;
use super::ts_names::{self, Owner, Scope};
use super::ts_struct_gen;
use super::ts_table_gen;
use super::CodeGenError;
use super::TsCodeGenOptions;
use crate::code_writer::CodeWriter;

const HEADER: &[&str] = &[
    "// automatically generated by flatc-rs, do not modify",
    "// @generated",
    "",
    "/* eslint-disable @typescript-eslint/no-unused-vars, @typescript-eslint/no-explicit-any, @typescript-eslint/no-non-null-assertion */",
];

/// A generated TypeScript file: path relative to the output directory
/// (`/`-separated) and contents.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TsFile {
    pub path: String,
    pub code: String,
}

/// Single-file TypeScript generator (`--ts-flat-files`): all types of the
/// schema in one file, grouped in nested `export namespace` blocks.
pub struct TsGenerator<'a> {
    pub schema: &'a ResolvedSchema,
    pub w: CodeWriter,
    pub opts: &'a TsCodeGenOptions,
}

impl<'a> TsGenerator<'a> {
    pub fn new(schema: &'a ResolvedSchema, opts: &'a TsCodeGenOptions) -> Self {
        Self {
            schema,
            w: CodeWriter::new(),
            opts,
        }
    }

    /// Generate all TypeScript code and return the source string.
    pub fn generate(mut self) -> Result<String, CodeGenError> {
        self.gen_header();
        self.gen_body()?;
        Ok(self.w.finish())
    }

    fn gen_header(&mut self) {
        for line in HEADER {
            if line.is_empty() {
                self.w.blank();
            } else {
                self.w.line(line);
            }
        }
        self.w.blank();
        self.w.line("import * as flatbuffers from 'flatbuffers';");
    }

    /// Group all types by namespace and emit them.
    fn gen_body(&mut self) -> Result<(), CodeGenError> {
        let root = namespace_tree::build_namespace_tree(self.schema, &self.opts.gen_only_files);

        // Emit root-level types
        if !root.types.is_empty() {
            self.w.blank();
            self.gen_types(&root.types, "")?;
        }

        // Emit child namespace modules
        for (name, child) in &root.children {
            self.gen_namespace_node(name, name, child)?;
        }
        Ok(())
    }

    /// Recursively emit a namespace node as `export namespace` blocks.
    fn gen_namespace_node(
        &mut self,
        name: &str,
        path: &str,
        node: &NamespaceNode,
    ) -> Result<(), CodeGenError> {
        self.w.blank();
        self.w.line(&format!("export namespace {name} {{"));
        self.w.indent();

        // Types at this namespace level
        if !node.types.is_empty() {
            self.w.blank();
            self.gen_types(&node.types, path)?;
        }

        // Child namespaces
        for (child_name, child_node) in &node.children {
            let child_path = format!("{path}.{child_name}");
            self.gen_namespace_node(child_name, &child_path, child_node)?;
        }

        self.w.dedent();
        self.w.line(&format!("}} // {name}"));
        Ok(())
    }

    fn gen_types(&mut self, entries: &[TypeEntry], ns: &str) -> Result<(), CodeGenError> {
        let _scope = Scope::flat(ns);
        for entry in entries {
            gen_type(&mut self.w, self.schema, entry, self.opts)?;
            self.w.blank();
        }
        Ok(())
    }
}

fn gen_type(
    w: &mut CodeWriter,
    schema: &ResolvedSchema,
    entry: &TypeEntry,
    opts: &TsCodeGenOptions,
) -> Result<(), CodeGenError> {
    match entry {
        TypeEntry::Enum(idx) => ts_enum_gen::generate(w, schema, *idx, opts.gen_object_api),
        TypeEntry::Struct(idx) => {
            ts_struct_gen::generate(w, schema, *idx, opts.gen_object_api);
            Ok(())
        }
        TypeEntry::Table(idx) => ts_table_gen::generate(w, schema, *idx, opts),
    }
}

fn entry_owner(entry: &TypeEntry) -> Owner {
    match entry {
        TypeEntry::Enum(i) => Owner::Enum(*i),
        TypeEntry::Struct(i) | TypeEntry::Table(i) => Owner::Obj(*i),
    }
}

/// Names a type's module exports, known before its body is generated so that
/// imported names can be aliased away from them.
fn own_exports(schema: &ResolvedSchema, entry: &TypeEntry, opts: &TsCodeGenOptions) -> Vec<String> {
    match entry {
        TypeEntry::Enum(i) => {
            let e = &schema.enums[*i];
            let mut v = vec![e.name.clone()];
            if e.is_union {
                v.push(format!("unionTo{}", e.name));
                v.push(format!("unionListTo{}", e.name));
                if opts.gen_object_api {
                    v.push(format!("{}T", e.name));
                }
            }
            v
        }
        TypeEntry::Struct(i) | TypeEntry::Table(i) => {
            let name = &schema.objects[*i].name;
            let mut v = vec![name.clone()];
            if opts.gen_object_api {
                v.push(format!("{name}T"));
            }
            v
        }
    }
}

/// Exported value names actually present in a generated module body.
fn exported_names(code: &str) -> Vec<String> {
    let mut names = Vec::new();
    for line in code.lines() {
        for prefix in ["export class ", "export enum ", "export function "] {
            if let Some(rest) = line.strip_prefix(prefix) {
                let name: String = rest
                    .chars()
                    .take_while(|c| c.is_ascii_alphanumeric() || *c == '_' || *c == '$')
                    .collect();
                if !name.is_empty() {
                    names.push(name);
                }
            }
        }
    }
    names
}

/// One-module-per-type TypeScript generator (upstream `flatc --ts` layout).
///
/// For a type `Name` in namespace `A.B` it writes `a/b/name.ts`; each
/// namespace gets a barrel module (`a/b.ts` re-exporting its types,
/// `a.ts` re-exporting `* as B`), and `<root_name>.ts` re-exports the
/// root-namespace types and `* as A`. Bundlers can tree-shake unused types.
pub fn generate_modules(
    schema: &ResolvedSchema,
    opts: &TsCodeGenOptions,
    root_name: &str,
) -> Result<Vec<TsFile>, CodeGenError> {
    let root = namespace_tree::build_namespace_tree(schema, &opts.gen_only_files);
    let mut files: BTreeMap<String, String> = BTreeMap::new();
    let mut add = |path: String, code: String| -> Result<(), CodeGenError> {
        if let Some(existing) = files.get(&path) {
            if *existing != code {
                return Err(CodeGenError::Internal(format!(
                    "TypeScript module path collision: two declarations map to '{path}'"
                )));
            }
        }
        files.insert(path, code);
        Ok(())
    };

    let root_barrel = gen_node_modules(schema, opts, &root, &[], &mut add)?;
    add(format!("{root_name}.ts"), root_barrel)?;

    Ok(files
        .into_iter()
        .map(|(path, code)| TsFile { path, code })
        .collect())
}

/// Generate the type modules of `node` (and its children) and return the
/// barrel module body for `node`.
fn gen_node_modules(
    schema: &ResolvedSchema,
    opts: &TsCodeGenOptions,
    node: &NamespaceNode,
    ns_dirs: &[String],
    add: &mut dyn FnMut(String, String) -> Result<(), CodeGenError>,
) -> Result<String, CodeGenError> {
    let mut barrel: Vec<String> = Vec::new();
    // Barrel for namespace `a/b` lives at `a/b.ts`; its types are in `a/b/`.
    let local_dir = ns_dirs
        .last()
        .map(|d| format!("./{d}/"))
        .unwrap_or_else(|| "./".to_string());

    for entry in &node.types {
        let owner = entry_owner(entry);
        let module_path = ts_names::owner_module_path(schema, owner);
        let (body, imports) = {
            let scope = Scope::module(schema, owner, &own_exports(schema, entry, opts));
            let mut w = CodeWriter::new();
            gen_type(&mut w, schema, entry, opts)?;
            let body = w.finish();
            (body, scope.import_lines())
        };

        let mut code = String::new();
        for line in HEADER {
            code.push_str(line);
            code.push('\n');
        }
        code.push('\n');
        if body.contains("flatbuffers.") {
            code.push_str("import * as flatbuffers from 'flatbuffers';\n\n");
        }
        if !imports.is_empty() {
            for line in &imports {
                code.push_str(line);
                code.push('\n');
            }
            code.push('\n');
        }
        code.push_str(body.trim_end());
        code.push('\n');

        let names = exported_names(&body);
        let file = module_path.last().cloned().unwrap_or_default();
        barrel.push(format!(
            "export {{ {} }} from '{local_dir}{file}.js';",
            names.join(", ")
        ));
        add(format!("{}.ts", module_path.join("/")), code)?;
    }

    for (child_name, child) in &node.children {
        let mut child_dirs = ns_dirs.to_vec();
        child_dirs.push(ts_names::to_dasher(child_name));
        let child_barrel = gen_node_modules(schema, opts, child, &child_dirs, add)?;
        add(format!("{}.ts", child_dirs.join("/")), child_barrel)?;
        let child_file = child_dirs.last().unwrap();
        barrel.push(format!(
            "export * as {child_name} from '{local_dir}{child_file}.js';"
        ));
    }

    let mut code = String::new();
    for line in HEADER {
        code.push_str(line);
        code.push('\n');
    }
    code.push('\n');
    for line in &barrel {
        code.push_str(line);
        code.push('\n');
    }
    Ok(code)
}
